CREATE FUNCTION pg_temp.redaction_call(p_operation text,p_args jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE actor uuid;admission uuid;r jsonb;
BEGIN
 SELECT auth_user_id INTO actor FROM public.sandy_controller_admins WHERE role='owner' AND enabled ORDER BY created_at LIMIT 1;
 admission:=pg_temp.sandy_owner_component_admission(p_operation,p_args,'b686b66a7f00b944a9aca973b3cc1e7d2d5e322b429246006d9662da011e17c8');
 r:=public.sandy_tenant_financial_redaction_execute(actor,admission,p_args::text);
 IF r->>'ok'<>'true' OR public.sandy_tenant_financial_redaction_execute(actor,admission,p_args::text) IS DISTINCT FROM(r||jsonb_build_object('reused',true)) THEN RAISE EXCEPTION 'financial_redaction_receipt_invalid';END IF;
 RETURN r->'result';
END $$;
